impl ContourGenerator {
    /// Create a new contour generator for a grid of the given dimensions.
    pub fn new(width: usize, height: usize) -> Self {
        Self {
            width,
            height,
            x0: 0.0,
            y0: 0.0,
            x1: width as f64,
            y1: height as f64,
            x_values: None,
            y_values: None,
            upsample_factor: 1,
            x_log_interpolation: false,
            y_log_interpolation: false,
            visited_cache: Rc::new(RefCell::new(None)),
            upsampled_buf: Rc::new(RefCell::new(Vec::new())),
            band_points: Rc::new(RefCell::new(Vec::new())),
            band_crossings: Rc::new(RefCell::new(Vec::new())),
        }
    }

    /// Set the x range for the contour output (linear interpolation between x0 and x1).
    pub fn x(mut self, x0: f64, x1: f64) -> Self {
        self.x0 = x0;
        self.x1 = x1;
        self.x_values = None; // Clear explicit values when using range
        self
    }

    /// Set the y range for the contour output (linear interpolation between y0 and y1).
    pub fn y(mut self, y0: f64, y1: f64) -> Self {
        self.y0 = y0;
        self.y1 = y1;
        self.y_values = None; // Clear explicit values when using range
        self
    }

    /// Set explicit x values for each column.
    /// This allows non-linear spacing (e.g., log-spaced frequency values).
    /// The length must equal the grid width.
    pub fn x_values(mut self, values: Vec<f64>) -> Self {
        if values.len() == self.width {
            self.x_values = Some(values);
        }
        self
    }

    /// Set explicit y values for each row.
    /// This allows non-linear spacing.
    /// The length must equal the grid height.
    pub fn y_values(mut self, values: Vec<f64>) -> Self {
        if values.len() == self.height {
            self.y_values = Some(values);
        }
        self
    }

    /// Set an optional scalar-field upsample factor before contour extraction.
    ///
    /// A factor of 1 preserves the original marching-squares grid. Higher
    /// values create denser bilinearly interpolated cells, which reduces
    /// faceting on coarse grids at additional CPU cost.
    pub fn upsample_factor(mut self, factor: usize) -> Self {
        self.upsample_factor = factor.clamp(1, 8);
        self
    }

    /// Interpolate explicit x values in log space when values are positive.
    pub fn x_log_interpolation(mut self, enabled: bool) -> Self {
        self.x_log_interpolation = enabled;
        self
    }

    /// Interpolate explicit y values in log space when values are positive.
    pub fn y_log_interpolation(mut self, enabled: bool) -> Self {
        self.y_log_interpolation = enabled;
        self
    }

    /// Run `f` with a freshly-cleared `visited` buffer sized for the current grid.
    fn with_visited<R>(&self, f: impl FnOnce(&mut [bool]) -> R) -> R {
        let needed = self.width * self.height * 4;
        let mut cache = self.visited_cache.borrow_mut();
        match cache.as_mut() {
            Some((w, h, buf)) if *w == self.width && *h == self.height => {
                buf.fill(false);
            }
            _ => {
                *cache = Some((self.width, self.height, vec![false; needed]));
            }
        }
        let buf = &mut cache.as_mut().unwrap().2;
        f(buf)
    }

    /// Upsample `values` into `out` and return a generator for the upsampled grid.
    ///
    /// Returns `None` when upsampling is not required or not possible.
    fn upsampled_into(&self, values: &[f64], out: &mut Vec<f64>) -> Option<Self> {
        let factor = self.upsample_factor;
        if factor <= 1
            || self.width < 2
            || self.height < 2
            || values.len() < self.width * self.height
        {
            return None;
        }

        let new_width = (self.width - 1) * factor + 1;
        let new_height = (self.height - 1) * factor + 1;
        out.resize(new_width * new_height, 0.0);

        for y in 0..new_height {
            let source_y = y as f64 / factor as f64;
            let y0 = (source_y.floor() as usize).min(self.height - 2);
            let ty = source_y - y0 as f64;

            for x in 0..new_width {
                let source_x = x as f64 / factor as f64;
                let x0 = (source_x.floor() as usize).min(self.width - 2);
                let tx = source_x - x0 as f64;

                let z00 = values[y0 * self.width + x0];
                let z10 = values[y0 * self.width + x0 + 1];
                let z01 = values[(y0 + 1) * self.width + x0];
                let z11 = values[(y0 + 1) * self.width + x0 + 1];

                let z0 = z00 + (z10 - z00) * tx;
                let z1 = z01 + (z11 - z01) * tx;
                out[y * new_width + x] = z0 + (z1 - z0) * ty;
            }
        }

        Some(Self {
            width: new_width,
            height: new_height,
            x0: self.x0,
            y0: self.y0,
            x1: self.x1,
            y1: self.y1,
            x_values: self.x_values.as_ref().map(|values| {
                upsample_axis_values(values, factor, new_width, self.x_log_interpolation)
            }),
            y_values: self.y_values.as_ref().map(|values| {
                upsample_axis_values(values, factor, new_height, self.y_log_interpolation)
            }),
            upsample_factor: 1,
            x_log_interpolation: self.x_log_interpolation,
            y_log_interpolation: self.y_log_interpolation,
            visited_cache: Rc::new(RefCell::new(None)),
            upsampled_buf: Rc::new(RefCell::new(Vec::new())),
            band_points: Rc::new(RefCell::new(Vec::new())),
            band_crossings: Rc::new(RefCell::new(Vec::new())),
        })
    }

    /// Run `f` with the (possibly upsampled) values for this generator.
    ///
    /// Reuses the generator's upsampled-value buffer when upsampling is active.
    fn with_upsampled<R>(&self, values: &[f64], f: impl FnOnce(&Self, &[f64]) -> R) -> R {
        if self.upsample_factor > 1 {
            let mut buf = self.upsampled_buf.borrow_mut();
            if let Some(generator) = self.upsampled_into(values, &mut buf) {
                return f(&generator, &buf);
            }
        }
        f(self, values)
    }

    /// Generate a contour at the given threshold value, writing into `out`.
    pub fn contour_into(&self, values: &[f64], threshold: f64, out: &mut Contour) {
        self.with_upsampled(values, |this, vals| {
            this.contour_internal(vals, threshold, out)
        });
    }

    fn contour_internal(&self, values: &[f64], threshold: f64, out: &mut Contour) {
        out.value = threshold;
        out.coordinates.clear();

        if self.width < 2 || self.height < 2 || values.len() < (self.width * self.height) {
            return;
        }

        self.with_visited(|visited| {
            // For each cell, check if it crosses the threshold
            for j in 0..self.height - 1 {
                for i in 0..self.width - 1 {
                    let case = self.cell_case(values, i, j, threshold);

                    if case == 0 || case == 15 {
                        continue; // No contour crosses this cell
                    }

                    // Try to trace contours starting from edges that cross the threshold
                    for &edge in Self::crossing_edges(case) {
                        let idx = (j * self.width + i) * 4 + edge;
                        if visited[idx] {
                            continue;
                        }

                        if let Some(ring) =
                            self.trace_contour(values, threshold, i, j, edge, visited)
                            && ring.points.len() >= 3
                        {
                            out.add_ring(ring);
                        }
                    }
                }
            }
        });
    }

    /// Generate a contour at the given threshold value.
    pub fn contour(&self, values: &[f64], threshold: f64) -> Contour {
        let mut contour = Contour::new(threshold);
        self.contour_into(values, threshold, &mut contour);
        contour
    }

    /// Get the edges that have a crossing for a given case.
    pub(super) fn crossing_edges(case: u8) -> &'static [usize] {
        // For each case, return the edges that have a crossing
        // Edge 0 crosses if bits 0 and 1 differ
        // Edge 1 crosses if bits 1 and 2 differ
        // Edge 2 crosses if bits 2 and 3 differ
        // Edge 3 crosses if bits 3 and 0 differ
        match case {
            0 | 15 => &[],       // No crossings
            1 | 14 => &[0, 3],   // bottom and left
            2 | 13 => &[0, 1],   // bottom and right
            3 | 12 => &[1, 3],   // right and left
            4 | 11 => &[1, 2],   // right and top
            5 => &[0, 1, 2, 3],  // saddle: all edges
            6 | 9 => &[0, 2],    // bottom and top
            7 | 8 => &[2, 3],    // top and left
            10 => &[0, 1, 2, 3], // saddle: all edges
            _ => &[],
        }
    }

    /// Generate contours at multiple threshold values.
    pub fn contours(&self, values: &[f64], thresholds: &[f64]) -> Vec<Contour> {
        self.with_upsampled(values, |this, vals| {
            thresholds.iter().map(|&t| this.contour(vals, t)).collect()
        })
    }

    /// Generate independent cell-local contour segments for multiple thresholds.
    ///
    /// This avoids connecting traced rings across discontinuities and is useful
    /// for renderers that prefer to draw each marching-squares segment directly.
    pub fn contour_segments(&self, values: &[f64], thresholds: &[f64]) -> Vec<ContourSegment> {
        self.with_upsampled(values, |this, vals| {
            if this.width < 2 || this.height < 2 || vals.len() < (this.width * this.height) {
                return Vec::new();
            }

            let mut segments = Vec::new();
            for &threshold in thresholds {
                for j in 0..this.height - 1 {
                    for i in 0..this.width - 1 {
                        let case = this.cell_case(vals, i, j, threshold);
                        for &(edge_a, edge_b) in Self::cell_segment_edge_pairs(case) {
                            let Some(start) = this.edge_point(vals, i, j, edge_a, threshold) else {
                                continue;
                            };
                            let Some(end) = this.edge_point(vals, i, j, edge_b, threshold) else {
                                continue;
                            };
                            segments.push(ContourSegment::new(threshold, start, end));
                        }
                    }
                }
            }
            segments
        })
    }

    pub(super) fn cell_segment_edge_pairs(case: u8) -> &'static [(usize, usize)] {
        match case {
            0 | 15 => &[],
            1 | 14 => &[(0, 3)],
            2 | 13 => &[(0, 1)],
            3 | 12 => &[(1, 3)],
            4 | 11 => &[(1, 2)],
            5 => &[(0, 1), (2, 3)],
            6 | 9 => &[(0, 2)],
            7 | 8 => &[(2, 3)],
            10 => &[(0, 3), (1, 2)],
            _ => &[],
        }
    }

    #[allow(dead_code)] // Used only by tests and the internal `_into` helpers.
    pub(super) fn upsampled(&self, values: &[f64]) -> Option<(Self, Vec<f64>)> {
        let mut out = Vec::new();
        self.upsampled_into(values, &mut out).map(|g| (g, out))
    }

    /// Compute the marching squares case for a cell.
    pub(super) fn cell_case(&self, values: &[f64], i: usize, j: usize, threshold: f64) -> u8 {
        let v00 = values[j * self.width + i];
        let v10 = values[j * self.width + i + 1];
        let v01 = values[(j + 1) * self.width + i];
        let v11 = values[(j + 1) * self.width + i + 1];

        let mut case = 0u8;
        if v00 >= threshold {
            case |= 1;
        }
        if v10 >= threshold {
            case |= 2;
        }
        if v11 >= threshold {
            case |= 4;
        }
        if v01 >= threshold {
            case |= 8;
        }
        case
    }

    /// Trace a contour starting from a cell and edge.
    pub(super) fn trace_contour(
        &self,
        values: &[f64],
        threshold: f64,
        start_i: usize,
        start_j: usize,
        start_edge: usize,
        visited: &mut [bool],
    ) -> Option<ContourRing> {
        let mut points = Vec::new();
        let mut i = start_i;
        let mut j = start_j;
        let mut entry_edge = start_edge;

        loop {
            // Mark this entry edge as visited
            let idx = (j * self.width + i) * 4 + entry_edge;
            if visited[idx] {
                break;
            }
            visited[idx] = true;

            // Get the interpolated point on the entry edge
            if let Some(point) = self.edge_point(values, i, j, entry_edge, threshold) {
                points.push(point);
            }

            // Find the exit edge within this cell
            let case = self.cell_case(values, i, j, threshold);
            let exit_edge = match Self::exit_edge(entry_edge, case) {
                Some(e) => e,
                None => break,
            };

            // Also mark the exit edge as visited (it's the same contour segment)
            let exit_idx = (j * self.width + i) * 4 + exit_edge;
            visited[exit_idx] = true;

            // Move to the adjacent cell
            match self.move_to_adjacent_cell(i, j, exit_edge) {
                Some((next_i, next_j, next_entry)) => {
                    // Check if we've returned to the start
                    if next_i == start_i && next_j == start_j && next_entry == start_edge {
                        break;
                    }
                    i = next_i;
                    j = next_j;
                    entry_edge = next_entry;
                }
                None => {
                    // Hit boundary, contour is open
                    break;
                }
            }
        }

        // Remove consecutive duplicate points (can occur when values are exactly on threshold)
        let mut deduped = Vec::with_capacity(points.len());
        for pt in points {
            if deduped.is_empty() || !points_equal(&deduped[deduped.len() - 1], &pt) {
                deduped.push(pt);
            }
        }

        // Close the ring if we have enough points
        if deduped.len() >= 3 {
            // Only add closing point if it's different from the last point
            if !points_equal(&deduped[deduped.len() - 1], &deduped[0]) {
                deduped.push(deduped[0]);
            }
            Some(ContourRing::new(deduped))
        } else {
            None
        }
    }

    /// Get the interpolated point on an edge.
    pub(super) fn edge_point(
        &self,
        values: &[f64],
        i: usize,
        j: usize,
        edge: usize,
        threshold: f64,
    ) -> Option<Point> {
        let (x0, y0, x1, y1, v0, v1) = match edge {
            0 => {
                // Bottom edge (i,j) to (i+1,j)
                let v0 = values[j * self.width + i];
                let v1 = values[j * self.width + i + 1];
                (i as f64, j as f64, (i + 1) as f64, j as f64, v0, v1)
            }
            1 => {
                // Right edge (i+1,j) to (i+1,j+1)
                let v0 = values[j * self.width + i + 1];
                let v1 = values[(j + 1) * self.width + i + 1];
                (
                    (i + 1) as f64,
                    j as f64,
                    (i + 1) as f64,
                    (j + 1) as f64,
                    v0,
                    v1,
                )
            }
            2 => {
                // Top edge (i+1,j+1) to (i,j+1)
                let v0 = values[(j + 1) * self.width + i + 1];
                let v1 = values[(j + 1) * self.width + i];
                (
                    (i + 1) as f64,
                    (j + 1) as f64,
                    i as f64,
                    (j + 1) as f64,
                    v0,
                    v1,
                )
            }
            3 => {
                // Left edge (i,j+1) to (i,j)
                let v0 = values[(j + 1) * self.width + i];
                let v1 = values[j * self.width + i];
                (i as f64, (j + 1) as f64, i as f64, j as f64, v0, v1)
            }
            _ => return None,
        };

        if (v1 - v0).abs() < 1e-10 {
            return None;
        }

        let t = (threshold - v0) / (v1 - v0);
        if !(0.0..=1.0).contains(&t) {
            return None;
        }

        let px = x0 + t * (x1 - x0);
        let py = y0 + t * (y1 - y0);

        Some(Point::new(self.transform_x(px), self.transform_y(py)))
    }

    /// Find the exit edge for a given entry edge and case.
    /// Returns the exit edge within this cell (0=bottom, 1=right, 2=top, 3=left).
    /// Returns None for cases 0 and 15 (no contour).
    pub(super) fn exit_edge(entry_edge: usize, case: u8) -> Option<usize> {
        // Standard marching squares lookup table
        // Entry edge -> exit edge for each case
        // Cases 0 and 15: no contour crossing
        // Cases 5 and 10: saddle points (ambiguous, we pick one interpretation)
        //
        // Case bit layout:
        //   bit 0 (1): bottom-left corner (i, j)
        //   bit 1 (2): bottom-right corner (i+1, j)
        //   bit 2 (4): top-right corner (i+1, j+1)
        //   bit 3 (8): top-left corner (i, j+1)
        //
        // Edge layout:
        //   0: bottom (between corners 0 and 1)
        //   1: right (between corners 1 and 2)
        //   2: top (between corners 2 and 3)
        //   3: left (between corners 3 and 0)

        match case {
            0 | 15 => None, // No contour

            // Single corner cases
            1 => match entry_edge {
                0 => Some(3),
                3 => Some(0),
                _ => None,
            }, // bottom-left above
            2 => match entry_edge {
                0 => Some(1),
                1 => Some(0),
                _ => None,
            }, // bottom-right above
            4 => match entry_edge {
                1 => Some(2),
                2 => Some(1),
                _ => None,
            }, // top-right above
            8 => match entry_edge {
                2 => Some(3),
                3 => Some(2),
                _ => None,
            }, // top-left above

            // Opposite corner cases (complement of single corner)
            14 => match entry_edge {
                0 => Some(3),
                3 => Some(0),
                _ => None,
            }, // complement of 1
            13 => match entry_edge {
                0 => Some(1),
                1 => Some(0),
                _ => None,
            }, // complement of 2
            11 => match entry_edge {
                1 => Some(2),
                2 => Some(1),
                _ => None,
            }, // complement of 4
            7 => match entry_edge {
                2 => Some(3),
                3 => Some(2),
                _ => None,
            }, // complement of 8

            // Two adjacent corners cases
            3 => match entry_edge {
                1 => Some(3),
                3 => Some(1),
                _ => None,
            }, // bottom two above
            6 => match entry_edge {
                0 => Some(2),
                2 => Some(0),
                _ => None,
            }, // right two above
            12 => match entry_edge {
                1 => Some(3),
                3 => Some(1),
                _ => None,
            }, // top two above
            9 => match entry_edge {
                0 => Some(2),
                2 => Some(0),
                _ => None,
            }, // left two above

            // Saddle cases (diagonal corners) - ambiguous, pick one interpretation
            5 => match entry_edge {
                // 0101: corners 0 and 2
                0 => Some(1),
                1 => Some(0),
                2 => Some(3),
                3 => Some(2),
                _ => None,
            },
            10 => match entry_edge {
                // 1010: corners 1 and 3
                0 => Some(3),
                3 => Some(0),
                1 => Some(2),
                2 => Some(1),
                _ => None,
            },

            _ => None,
        }
    }

    /// Move to the adjacent cell when exiting through an edge.
    /// Returns (new_i, new_j, entry_edge_in_new_cell) or None if at boundary.
    pub(super) fn move_to_adjacent_cell(
        &self,
        i: usize,
        j: usize,
        exit_edge: usize,
    ) -> Option<(usize, usize, usize)> {
        match exit_edge {
            0 => {
                // Exit through bottom -> enter cell below through its top
                if j > 0 { Some((i, j - 1, 2)) } else { None }
            }
            1 => {
                // Exit through right -> enter cell to the right through its left
                if i + 1 < self.width - 1 {
                    Some((i + 1, j, 3))
                } else {
                    None
                }
            }
            2 => {
                // Exit through top -> enter cell above through its bottom
                if j + 1 < self.height - 1 {
                    Some((i, j + 1, 0))
                } else {
                    None
                }
            }
            3 => {
                // Exit through left -> enter cell to the left through its right
                if i > 0 { Some((i - 1, j, 1)) } else { None }
            }
            _ => None,
        }
    }
}

impl ContourGenerator {
    /// Generate filled contour bands between consecutive threshold values.
    ///
    /// This method generates closed polygons for each band between consecutive
    /// threshold values. The bands are suitable for filled rendering.
    ///
    /// # Arguments
    /// * `values` - The grid values
    /// * `thresholds` - Threshold values (must be sorted in ascending order)
    ///
    /// # Returns
    /// A vector of ContourBand, one for each pair of consecutive thresholds.
    /// Generate filled contour bands between consecutive threshold values.
    pub fn contour_bands(&self, values: &[f64], thresholds: &[f64]) -> Vec<ContourBand> {
        let mut bands = Vec::new();
        self.contour_bands_into(values, thresholds, &mut bands);
        bands
    }

    /// Generate filled contour bands into `out`, reusing workspace buffers.
    ///
    /// `out` is cleared before appending one `ContourBand` per threshold pair.
    pub fn contour_bands_into(
        &self,
        values: &[f64],
        thresholds: &[f64],
        out: &mut Vec<ContourBand>,
    ) {
        out.clear();
        if thresholds.len() < 2 {
            return;
        }
        self.with_upsampled(values, |this, vals| {
            if this.width < 2 || this.height < 2 || vals.len() < (this.width * this.height) {
                return;
            }
            out.reserve(thresholds.len() - 1);
            for i in 0..thresholds.len() - 1 {
                let lower = thresholds[i];
                let upper = thresholds[i + 1];
                out.push(this.generate_band(vals, lower, upper));
            }
        });
    }

    /// Generate a single contour band between two threshold values.
    pub(super) fn generate_band(&self, values: &[f64], lower: f64, upper: f64) -> ContourBand {
        let mut band = ContourBand::new(lower, upper);
        let mut points = self.band_points.borrow_mut();
        let mut crossings = self.band_crossings.borrow_mut();

        for j in 0..self.height - 1 {
            for i in 0..self.width - 1 {
                if let Some(n) =
                    self.cell_band_polygon(values, i, j, lower, upper, &mut points, &mut crossings)
                    && n >= 3 {
                        let mut ring = Vec::with_capacity(n + 1);
                        ring.extend_from_slice(&points[..n]);
                        if !points_equal(&ring[0], &ring[n - 1]) {
                            ring.push(ring[0]);
                        }
                        band.polygons.push(ContourRing::new(ring));
                    }
            }
        }

        band
    }

    /// Generate the polygon fragment for a single cell in the band.
    ///
    /// Writes the fragment into `points` (which is cleared first) and returns
    /// the number of points, or `None` if the cell does not contribute.
    pub(super) fn cell_band_polygon(
        &self,
        values: &[f64],
        i: usize,
        j: usize,
        lower: f64,
        upper: f64,
        points: &mut Vec<Point>,
        crossings: &mut Vec<(f64, Point)>,
    ) -> Option<usize> {
        points.clear();
        crossings.clear();

        // Get the four corner values
        let v00 = values[j * self.width + i];
        let v10 = values[j * self.width + i + 1];
        let v01 = values[(j + 1) * self.width + i];
        let v11 = values[(j + 1) * self.width + i + 1];

        // Classify each corner: 0 = below lower, 1 = in band, 2 = above upper
        let c00 = Self::classify_value(v00, lower, upper);
        let c10 = Self::classify_value(v10, lower, upper);
        let c01 = Self::classify_value(v01, lower, upper);
        let c11 = Self::classify_value(v11, lower, upper);

        // If all corners are outside the band (all below or all above), no polygon
        if (c00 == 0 && c10 == 0 && c01 == 0 && c11 == 0)
            || (c00 == 2 && c10 == 2 && c01 == 2 && c11 == 2)
        {
            return None;
        }

        // If all corners are in the band, return the whole cell
        if c00 == 1 && c10 == 1 && c01 == 1 && c11 == 1 {
            let corners = self.cell_corners(i, j);
            points.extend_from_slice(&corners);
            return Some(4);
        }

        // Corner positions
        let corners = self.cell_corners(i, j);
        let corner_values = [v00, v10, v11, v01];
        let corner_classes = [c00, c10, c11, c01];

        // Walk around the cell, adding points where we're in the band
        for edge_idx in 0..4 {
            let curr_corner = edge_idx;
            let next_corner = (edge_idx + 1) % 4;
            let curr_class = corner_classes[curr_corner];
            let next_class = corner_classes[next_corner];
            let curr_val = corner_values[curr_corner];
            let next_val = corner_values[next_corner];

            // If current corner is in band, add it
            if curr_class == 1 {
                points.push(corners[curr_corner]);
            }

            // Check for crossings on this edge - collect both crossings if any
            crossings.clear();
            let val_diff = next_val - curr_val;

            // Avoid division by zero for flat edges
            if val_diff.abs() > 1e-10 {
                // Lower threshold crossing
                if (curr_class == 0 && next_class >= 1) || (curr_class >= 1 && next_class == 0) {
                    let t = (lower - curr_val) / val_diff;
                    if (0.0..=1.0).contains(&t) {
                        let x = corners[curr_corner].x
                            + t * (corners[next_corner].x - corners[curr_corner].x);
                        let y = corners[curr_corner].y
                            + t * (corners[next_corner].y - corners[curr_corner].y);
                        crossings.push((t, Point::new(x, y)));
                    }
                }

                // Upper threshold crossing
                if (curr_class <= 1 && next_class == 2) || (curr_class == 2 && next_class <= 1) {
                    let t = (upper - curr_val) / val_diff;
                    if (0.0..=1.0).contains(&t) {
                        let x = corners[curr_corner].x
                            + t * (corners[next_corner].x - corners[curr_corner].x);
                        let y = corners[curr_corner].y
                            + t * (corners[next_corner].y - corners[curr_corner].y);
                        crossings.push((t, Point::new(x, y)));
                    }
                }

                // Sort crossings by t value to ensure correct order along edge
                crossings
                    .sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));

                // Add sorted crossings to points
                for (_, pt) in crossings.iter().copied() {
                    points.push(pt);
                }
            }
        }

        // Remove duplicate consecutive points in place
        let mut write = 0;
        for read in 0..points.len() {
            if write == 0 || !points_equal(&points[write - 1], &points[read]) {
                points[write] = points[read];
                write += 1;
            }
        }
        points.truncate(write);

        if write >= 3 { Some(write) } else { None }
    }

    /// Classify a value relative to the band thresholds.
    /// Returns 0 if below lower, 1 if in band, 2 if above upper.
    pub(super) fn classify_value(value: f64, lower: f64, upper: f64) -> u8 {
        if value < lower {
            0
        } else if value > upper {
            2
        } else {
            1
        }
    }

    /// Get the four corners of a cell in output coordinates.
    pub(super) fn cell_corners(&self, i: usize, j: usize) -> [Point; 4] {
        let x0 = self.transform_x(i as f64);
        let x1 = self.transform_x((i + 1) as f64);
        let y0 = self.transform_y(j as f64);
        let y1 = self.transform_y((j + 1) as f64);

        [
            Point::new(x0, y0), // bottom-left
            Point::new(x1, y0), // bottom-right
            Point::new(x1, y1), // top-right
            Point::new(x0, y1), // top-left
        ]
    }

    /// Transform grid x coordinate to output coordinate.
    pub(super) fn transform_x(&self, px: f64) -> f64 {
        if self.width <= 1 {
            return self.x0;
        }
        if let Some(ref x_vals) = self.x_values {
            let idx = px.floor() as usize;
            let frac = px - px.floor();
            if idx + 1 < x_vals.len() {
                interpolate_axis_value(x_vals[idx], x_vals[idx + 1], frac, self.x_log_interpolation)
            } else if idx < x_vals.len() {
                x_vals[idx]
            } else {
                self.x0 + (px / (self.width - 1) as f64) * (self.x1 - self.x0)
            }
        } else {
            self.x0 + (px / (self.width - 1) as f64) * (self.x1 - self.x0)
        }
    }

    /// Transform grid y coordinate to output coordinate.
    pub(super) fn transform_y(&self, py: f64) -> f64 {
        if self.height <= 1 {
            return self.y0;
        }
        if let Some(ref y_vals) = self.y_values {
            let idx = py.floor() as usize;
            let frac = py - py.floor();
            if idx + 1 < y_vals.len() {
                interpolate_axis_value(y_vals[idx], y_vals[idx + 1], frac, self.y_log_interpolation)
            } else if idx < y_vals.len() {
                y_vals[idx]
            } else {
                self.y0 + (py / (self.height - 1) as f64) * (self.y1 - self.y0)
            }
        } else {
            self.y0 + (py / (self.height - 1) as f64) * (self.y1 - self.y0)
        }
    }
}
